{
  "findings": [
    {
      "check_id": "CKV_AZURE_113",
      "title": "SQL Server security alert policy has alerts disabled",
      "resource": "azurerm_mssql_server_security_alert_policy.recovery_db_alerts",
      "severity": "HIGH",
      "explanation": "The security alert policy for the SQL server has 'Sql_Injection' and 'Data_Exfiltration' alerts disabled, potentially missing critical security notifications."
    },
    {
      "check_id": "CKV_AZURE_25",
      "title": "SQL Server security alert policy retention days is less than 30",
      "resource": "azurerm_mssql_server_security_alert_policy.recovery_db_alerts",
      "severity": "MEDIUM",
      "explanation": "The retention period for security alerts is set to 20 days, which is less than the recommended 30 days, potentially leading to loss of historical alert data."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_server_security_alert_policy\" \"recovery_db_alerts\" {\n  resource_group_name        = azurerm_resource_group.dr_platform.name\n  server_name                = azurerm_mssql_server.recovery_sql_server.name\n  state                      = \"Enabled\"\n  storage_endpoint           = azurerm_storage_account.backup_storage.primary_blob_endpoint\n  storage_account_access_key = azurerm_storage_account.backup_storage.primary_access_key\n  disabled_alerts = []\n  retention_days = 30\n}",
  "fix_summary": "Enabled all security alerts and increased the retention period to 30 days to ensure comprehensive security monitoring and adequate log retention."
}
